  VALUES 
    (494::BIGINT, 'Explica con mucha claridad, es muy atento y ayuda mucho con las dudas que pueda tener, además le gusta hacer chistes en las explicaciones para sumarle humor a las clases. Lo considero de los mejores del TEC.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'f68ba500d5b4c8dc1581c291b73d60aee2f858919d2afcab59d8caa8a5772d4f'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'muy buen profe, explica muy bien y las clases se hacen cortas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-11-19T00:00:00+00:00'::TIMESTAMPTZ, '7939d5e043fcc567a0d624e4635b6c2358c2ccf8218041cdcca05f57a35a30c6'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'El mejor profe por mucho. se toma el tiempo de explicar, explica super claro y es demasiado paciente. Se interesa mucho en que el estudiante aprenda y termina uno hasta emocionado aprendiendo. Es el profe con más vocación que hay en el Tec, nunca duden en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-05T00:00:00+00:00'::TIMESTAMPTZ, '15964fa2ca18b81f7ed7ad12202cad3d9173a12104bc83fd0066087701ce9d0a'::TEXT, ARRAY[563, 634]::BIGINT[]),
    (494::BIGINT, 'Explica bastante bien, se nota su deseo por ayudar y que el estudiante entienda. Muy buen profesor y persona.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '03cb047943c903e2a9c7b0517e025e49010883aec6742181b96809ed9b629f1d'::TEXT, ARRAY[1672]::BIGINT[]),
    (494::BIGINT, 'Lleven cualquier curso con él, es el profesor más sensato y con vocación que he conocido, a parte de planear los cursos de forma excelente sin afán de perjudicar a los estudiantes . Por favor, sean buenos con él y pónganle a sacar buenas notas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-02-02T00:00:00+00:00'::TIMESTAMPTZ, '9b457c413a01ddc09038be6acd3c01317ddf9adeb02b65f58261fc529f705f29'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'El curso no es difícil y el profe hace que sean 1000 veces más fácil. Es súper pura vida, califica suave y enseña muy bien. Tiene todo el curso grabado, es muy paciente con dudas y hasta hace chistes en clase, el último día hasta nos compró pizza, 100% recomendado, el mejor profe de mate que tuve'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-04T00:00:00+00:00'::TIMESTAMPTZ, '4bbe7de453bb0972e0ef73605fe98c900976cab93753e11f8bc4527e6a72f4ca'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Sencillamente el mejor profe con el que pude haber matriculado mi primer semetre de la U. El mae es demasiado tuannis, explica super bien con ejemplos y ejercicios de todo tipo. Casi no deja tareas y las que deja no son pesadas. Los exámenes califica tratando de ayudarlo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'dd4a3439c0425085a33f7a3970aa478ec5e5c81b1d13eb38fc73a1ee4cdf309c'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'excelente persona, como profe bueno pero para los examenes si es indispensable hacer más ejercicios/más complejos, la mejor opción son examenes de años anteriores y puede considerar el curso pasado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'c251374ca344ad3daaf90ce1f685e775c026fbaae61872d1d4b352c2d6f9d46a'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'El mejor profe de CAL. Es todo divertido en clase y califica súper suave, es un osito jaja. La materia la explica muy bien, lo malo es que hace ejercicios un poco básicos, pero haciendo exámenes de semestres anteriores más el 25% que él asigna (son tareas fáciles) se pasa hasta con 100. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e29efab9e6a81b4f923d8e982711d76ff305b0b24329e266d3a6a2825ce32e27'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Soy una persona que trabaja y estudia, esta opción con este profe fue genial. Muy accesible y clara la materia durante el semestre. El profe estuvo comprometido con el apoyo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-11-09T00:00:00+00:00'::TIMESTAMPTZ, '04f00acf399426030b01a26423803174f8c73e6729e220d11db7e1673a676fd8'::TEXT, ARRAY[3477]::BIGINT[]),
    (494::BIGINT, 'De los mejores profes para mates. Simpático, explica muy claro, tiene mucho material, sus evaluaciones son fáciles y califica bastante justo. Cualquier duda dentro o fuera del aula la responde con toda la paciencia del mundo. Recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-25T00:00:00+00:00'::TIMESTAMPTZ, '47ea12c15538014d3249f846ef7209a303b782a2cfe5b6a71e7da217cec11595'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'e700963fcb76b13137dffa7e4f5813616e284b954af88107d2af283450cc3563'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Sin duda, uno de los mejores profes para llevar este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-20T00:00:00+00:00'::TIMESTAMPTZ, '8ef5d549b0395f9f4ce84d88341e23250842eaf575ca8ae5f75332ac49fc271f'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'un curso con mucha tecnologia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-12-31T00:00:00+00:00'::TIMESTAMPTZ, 'cb8ff5c23f81e897d5cb6dbf7fcabe9b36de29bd23e14992e171e57307b52825'::TEXT, ARRAY[1687]::BIGINT[]),
    (494::BIGINT, 'Las clases suselen ser presentacione sy discusiones grupales. Un curso que prepara para el uso de la historia en matemática'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '62f9a2c28961a9222cc041e13e2b1555e1be98ecef79b4130ffa2138bd7c61e1'::TEXT, ARRAY[3473]::BIGINT[]),
    (494::BIGINT, 'Es muy buena nota, califica normal y las "otras evaluaciones" son tareas y khan academy. Explica normal y sus clases no siempre son las más provechosas. Recomiendo estudiar mucho independiente (sus ejercicios no preparan lo necesario) y hacerle consultas por telegram (siempre está atento a ayudar).'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '652ed564efed5e7012848c14ba452f1ab67fea48f08f714a78e7a647e89c9918'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Super bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-04-28T00:00:00+00:00'::TIMESTAMPTZ, 'dd45514ac39a29dc2451ea2a5c143fce009316cc58d86e903cb39d3dff46e4d8'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Excelente profe, explica muy bien!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-04-28T00:00:00+00:00'::TIMESTAMPTZ, '961ff07b29f8c924cfb51aa5f3e27691e80645011c02a707e35f66b694b83e35'::TEXT, ARRAY[563]::BIGINT[]),
