    (494::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'bde95b78e87eca5c624bc58a15b1807cd00cf9f381e94569ef5fde5a0ce070d6'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '327ac9bf908708f8e5ca9b15ffe3276b64fc781cd30402cf3d5a20566d5890b2'::TEXT, ARRAY[261, 2444]::BIGINT[]),
    (494::BIGINT, 'Es un excelente profesor!! Tiene un verdadero talento de enseñar y motivar a los estudiantes. Las clases son completas y amenas- uno nunca pierde el interés de la materia en ningún momento. Si tiene la oportunidad de matricular con él, sepa que aprenderá de verdad :) 100/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-01-04T00:00:00+00:00'::TIMESTAMPTZ, '390532e1e3352c0ce7f38e714aa70f64e6f35a56dcc647d8399822492e19277c'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'EXCELENTE PROFE. Uno de los mejores, en definitiva. Las tareas son cortas y sencillas. Siempre está dispuesto a atender dudas y explica súper claro. 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8bf4d6a93e6633cfcec250ba51c0d6a04fbce4d7b82c1ea611b2d2cd8e220bcb'::TEXT, ARRAY[261, 2444]::BIGINT[]),
    (494::BIGINT, 'Es un excelente profe. Practicar mucho y no dejar que la materia se acumule'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'b46b6b83e5c9405c418a59fe66b70a990700cf904638ec964ebd203aacd7c729'::TEXT, ARRAY[261, 2444]::BIGINT[]),
    (494::BIGINT, 'Es el mejor profesor, super fácil pasar con él y explica increíble'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '2ac3224140a2296f632b288ab548782b7c8d4e2b5ae765e89ed41c3b7aebe910'::TEXT, ARRAY[261, 2444]::BIGINT[]),
    (494::BIGINT, 'Probablemente el MEJOR profesor que se vayan a topar a lo largo de sus carreras. Es increíble el apoyo que tiene a sus estudiantes, la empatía en las últimas semanas del semestre, la paciencia para explicar, y la disponibilidad por mensajes/correos/horas de consulta. No dude en llevar con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'e718f2adbb29e4e54a71929206c9b664d3229091be0169a635b556f2718a6c38'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Es un profesor EXTRAORDINARIO. Súper recomendado. Es muy buena nota, explica súper bien, no tiene problema con explicar nuevamente y las veces que sean necesarias, es muy organizado, las tareas son cortas, hace la clase interesante. Si tienen la oportunidad, no duden en matricular con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '4fa2b39354ead21ff8286cf5ac46e2e567777ada097f322fde01ba6ae8a34edc'::TEXT, ARRAY[261, 2444]::BIGINT[]),
    (494::BIGINT, 'Es una excelente persona y profe, explica muy muy claro y es muy muy pura vida. Las tareas que dejó eran muy cortas y la verdad muy fáciles. Soy pésimo en mate pero gracias a él saqué 90 en el segundo examen xd, en mi opinión el mejor profe de mate que he tenido y que hay en el tec'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'b8cde5f559a6857caf5fe5263317a65a55b5d78d62f5a98e7fc06130e44a37d5'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'El profe es un crack, siempre explica todo muy claro y siempre está disponible para ayudarlo a uno, sabe explicar muy bien y aclara todas las preguntas que se le hacen, 10/10'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '39a671912955257c3c37f7840c689d025e66e1d2c00710963fbc573e1b8ad28a'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Es un buen profesor, explica bastante bien y siempre está dispuesto a ayudar a los estudiantes. Sin embargo, puede resultar difícil para las personas con déficit atencional, ya que hace comentarios que no tienen nada que ver con la clase, lo que hace que los estudiantes pierdan el hilo del tema.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'fd471d8a9192fef2d237ff915593eb85b251f396e783b8d9366720e9144c738e'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '037d0909c4a2bf01ab084e0b98d4dcf41b4bdc5348941b2255ac5ae82fb74e3e'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'Es un profesor EXTREMADAMENTE bueno, el mejor que he conocido en mucho tiempo. Lo recomiendo full, súper atento, organizado, responsable, buena nota y dispuesto a ayudar. Da las clases de una forma dinámica y se aprende bastante con él. Hace que el curso sea placentero.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '8a9b6c0385c788624d8329c5ca1980cc1c729d8cb47e3668f39639792db69754'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'El profe es extremadamente bueno. Era la primera vez que daba cálculo y álgebra lineal y se lució montones. Las clases eran súper bonitas y él explicaba de lo mejor. Las tareas eran sencillas y las prácticas que deja ayudan mucho para exámenes y quices. Siempre atiende dudas por telegram. Lo adoro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '07488159f8bd71c25768b98fb0d7d7094c6e6113e8c20b3045bc1cf09c65cb67'::TEXT, ARRAY[634]::BIGINT[]),
    (494::BIGINT, 'El profe es demasiado pura vida, explica las veces que usted necesite y lo hace de muy buena gana. Súper ordenado y claro con respecto a asignaciones y la clase en general. Meta lo que sea con él, de fijo lo pasa.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-18T00:00:00+00:00'::TIMESTAMPTZ, '00828037853b1c2b4325a84900bafafba49c4c8f3a2553ae8225c1c1e430302b'::TEXT, ARRAY[563]::BIGINT[]),
