    (494::BIGINT, 'El profe es excelente, es de lo mejor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '356416f1325b5d5d69764f529403c2cd82b98549c699d2099ff97df1ed221b0d'::TEXT, ARRAY[1687]::BIGINT[]),
    (494::BIGINT, 'Excelente profe, explica súper claro y se preocupa q todos entiendan la materia, aunque tenga q repetir la materia varias veces. Hace las clases súper llevaderas... si puede matricular con él sería el éxito'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '4f4c8c62495d7499459dfd62ac3b2263cfb559ba6aa9dc2d888c70fd4134091b'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '0102c9f1552be702f984e391754f3f88ed703ab804adc5e5df3377b29288289c'::TEXT, ARRAY[2439]::BIGINT[]),
    (494::BIGINT, 'Simplemente excelente. Se preocupa porque el estudiante entienda y siempre está a disposición para aclarar dudas. En modalidad virtual se adaptó muy bien. Si tiene la oportunidad de matricular con él, no lo dude.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'bc2b91e283cf15569156fba4dac129eaced7cfe2afedf20f0db47aa9cb9bfe05'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Excelente profe, se nota la vocación. Es dificil quedarse con él'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'c16fadee9ddb500f42aa35d41360dde821ed611cffef132295e33840cf6593b6'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Explica súper bien y brinda mucha ayuda! En modalidad virtual es excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '44f3ffd010d225a9ce409e8ce9e54b0b139e15e60f245fc990c4388bec71a35e'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'En virtual, y presencial, es un amor. Como dice un comentario, hasta con manzanitas explica si es necesario. Responde correos, mensajes, dudas, incluso a las 11 de la noche. Recomendadísimo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'b893b2e6f762f50a293920c229ec4bd3d4236c257389cd498b1b53e199895055'::TEXT, ARRAY[563]::BIGINT[]),
