    (494::BIGINT, 'Tiene toda la vocación de profesor, se toma el tiempo para explicar y vuelve de ser necesario. Explica muy claro y es muy entretenido. Se adaptó perfectamente a la modalidad virtual'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'e6ad64a9ad264dbd403bb87eba3db06fe3dc91451ddca9eda8005eccaabb5b72'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'd9e7bd8d7800c90b3981d119f50e9337edcb6328f69cdafbe630226f3d8e9112'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-02T00:00:00+00:00'::TIMESTAMPTZ, '0a3655928fb81449402133ff7bd9c4715ff7a5232496d8d63e573c3a695e83a2'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Este profe entiende al 100% el significado de ser profesor, te explica con manzanas si es necesario, te pone ejemplos fáciles para que usted entienda lo que estudia y no sólo estudie para pasar el examen si no para entender porque es importante la materia, un 100 para este profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'edf0be5924209877aa9ab8859e0a95dd0332894db4086719533409a7d511cde6'::TEXT, ARRAY[1026]::BIGINT[]),
    (494::BIGINT, 'Un profesor sumamente buena gente, explica bien, las clases son entretenidas, ayuda mucho, si se estudia la práctica de examen se sale excelente en el examen. Si puede matricular con él, hágalo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-07T00:00:00+00:00'::TIMESTAMPTZ, '8b2ba01d6e7f716630f1a432eeeac1f6ad7a56b4ecad6a1e66ae2673d1325703'::TEXT, ARRAY[2439]::BIGINT[]),
    (494::BIGINT, 'Él es un cosi, explica súper bien y de forma que uno entienda, ayuda un montón y siempre pasa por cada pupitre a aclarar dudas. Hace muchas prácticas para que uno haga, lo cual ayuda. Hace los quices para la casa y atiende dudas por WhatsApp. Es una excelente persona.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, '46612357a757aa67c435d3d4f74ddceb7c7aceacb7c581c0f8b5117cca55798b'::TEXT, ARRAY[605]::BIGINT[]),
    (494::BIGINT, 'Un profesor excelente! Dedica tiempo de más a todos. Lástima que no da verano!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '6fa8656860a45af6a70ddfd26832fab6d235b99b475638db80a39188a2959761'::TEXT, ARRAY[605]::BIGINT[]),
    (494::BIGINT, 'MATRICULE TODO LO QUE PUEDA CON EL es un amor y enseña súper bien, atiende cualquier duda.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f72a253c7ce517773764d582629966574c2956edfba9a85ee115638da868af88'::TEXT, ARRAY[1034]::BIGINT[]),
    (494::BIGINT, 'Exelente profesor, para la modalidad del plan piloto casi no hay practica y el toma se tiempo para hacerla, y sirven demasiado en el examen. Explica bien en clases, solo que el curso es largo asi que se tiene que practicar en casa como cualquier mate.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'df5105345000af7c98f20ab1fec26d9a8b6452fe1854567e3a6d879dc01cadaf'::TEXT, ARRAY[605]::BIGINT[]),
