    (494::BIGINT, 'Mi mejor profe del semestre. Ayuda un montón y hace las clases muy amenas. Si no entiende algo es solo preguntarle, él explica super bien y se interesa mucho por el estudiante. No califica duro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a3d35ec42ac2ee29683474c32e59ea05e0af8b67542c77ee4de797fc979cf5fc'::TEXT, ARRAY[563]::BIGINT[]),
    (494::BIGINT, 'Excelente profesor y persona, si tiene la oportunidad de matricular con el hágalo sin dudarlo. Resuelve cualquier duda durante la clase, da muy buenos ejemplos y practicas que son muy útiles en el curso, si necesita ayuda en el curso o cualquier otro de mate con mucho gusto lo ayudara. De lo mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1880d5a111cb843ce1e0de52476a7a293b3347f2c56a705ad7cd1b229c819de8'::TEXT, ARRAY[563]::BIGINT[]),
