    (494::BIGINT, 'No dude en llevar cualquier Mate con él, es un crack. Da ejemplos para que uno pueda entender la materia y explica las veces que sea necesario, crea mucha confianza y las clases son muy divertidas, definitivamente el mejor profe de la escuela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '97e0f9ae436b83943cb24507ca86dc579ad297488e581be732c5f13cf32cfa21'::TEXT, ARRAY[261, 2444]::BIGINT[]),
    (494::BIGINT, 'Excelente profesor. Conocedor, inspiracional. No dudaria en llevar otro curso con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '204ae39bd094f64d0e35615c897538318d439879335dba13fcee5b6578428f35'::TEXT, ARRAY[1711]::BIGINT[]),
    (494::BIGINT, 'Lo persona que escribe lo de abajo no tiene porqué calificar mal al profesor si nunca ha recibido clases con el. El problema no es del profesor sino del sistema con que ponen a otro profesores. Es una persona excelente. Espero que tenga un criterio antes de escribir aqui'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-03-19T00:00:00+00:00'::TIMESTAMPTZ, '8444ff2361b4339a120b92f81b99acfc6c648a2e20af2c4b4a43ea2b3b191636'::TEXT, ARRAY[261, 2444]::BIGINT[]),
