    (494::BIGINT, 'Sin lugar a dudas un crack de profe. No se pierda ni una clase. Explica excelente. hace ejemplos difíciles para prepararlo a uno. Le importa los estudiantes y busca fortalecer la comunicacion de estudiante profesor. De paso, es un cosi'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '999aac439217193679cd0dd839f4b883897a2731f7a5d8fa38ee66c7bfdb66d7'::TEXT, ARRAY[605]::BIGINT[]),
